import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
def load(f):return pd.read_csv(f)
fs=['train/A_vref_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_vref_op3.csv','train/A_line_op3.csv']
D=[load(f) for f in fs]
def lag(x,T,dt=1e-3):
    a=dt/(T+dt);return lfilter([a],[1,a-1],x,zi=[x[0]*(1-a)])[0]
def sim(p,d):
    kq,Tq,kp,Tp,Tw=p
    V=d.voltage_pu.values;th=d.bus_angle_rad.values;vs=d.voltage_setpoint_pu.values
    w=(th-lag(th,Tw))/Tw  # filtered derivative
    Q=d.reactive_power_pu.values[0]+lag(kq*(vs-V)-kq*(vs[0]-V[0]),Tq)
    P=d.active_power_pu.values[0]+lag(-kp*w,Tp)
    return P,Q
def res(p):
    r=[]
    for d in D:
        P,Q=sim(np.abs(p),d);r+=[(P-d.active_power_pu.values)[::20],(Q-d.reactive_power_pu.values)[::20]]
    return np.concatenate(r)
s=least_squares(res,[10,.1,1,.1,.05]);print(np.abs(s.x),s.cost)
for d in D:
    P,Q=sim(np.abs(s.x),d);print(np.std(P-d.active_power_pu),np.std(d.active_power_pu),np.std(Q-d.reactive_power_pu),np.std(d.reactive_power_pu))
